// Lista blanca de consultas. El llamador elige por nombre; la SQL no viaja nunca por
// la red. Todas son SELECT y todas toman un único $1.
const CONSULTAS = {
  // ¿Con qué formato están guardadas las sesiones? Contesta si el session_id
  // histórico de Kommo lleva el '+' del teléfono o no — de eso depende que los leads
  // en curso conserven su memoria en el cutover.
  sesiones: `SELECT session_id, count(*)::int AS mensajes, max(id) AS ultimo_id
             FROM n8n_chat_histories
             WHERE session_id LIKE $1
             GROUP BY session_id ORDER BY max(id) DESC LIMIT 25`,

  // Los últimos mensajes de una sesión, para ver qué quedó escrito en la memoria
  // compartida (incluidos los {"step":"step_N"} del Router).
  mensajes: `SELECT id, message->>'type' AS tipo,
                    left(message->>'content', 220) AS contenido
             FROM n8n_chat_histories WHERE session_id = $1
             ORDER BY id DESC LIMIT 20`,

  // Estado de la caché del catálogo que alimenta a W3.
  fichas: `SELECT count(*)::int AS total,
                  count(media_url)::int AS con_asset,
                  max(refrescado_at) AS refrescado
           FROM hpf_fichas WHERE nombre ILIKE $1`,

  // El mapeo contacto GHL -> session_id que arma W1.
  identidad: `SELECT ghl_contact_id, phone_e164, session_id, created_at
              FROM hpf_identity WHERE ghl_contact_id LIKE $1
              ORDER BY created_at DESC LIMIT 25`,

  // Estado de la cola de seguimientos de una sesión.
  seg_fila: `SELECT * FROM hpf_seguimientos WHERE session_id = $1`,

  // ── Mutaciones SÓLO DE TEST ───────────────────────────────────────────────────
  // Rompen la regla de "todo es SELECT" a propósito y con límites duros: son
  // sentencias FIJAS (no hay SQL del llamador), tocan UNA sola tabla —
  // `hpf_seguimientos`, que sólo usa el stack nuevo— y siempre filtran por
  // `session_id = $1`.
  //
  // Existen porque la cadencia real es de 1 a 29 horas: sin poder adelantar el reloj,
  // la máquina de seguimientos sólo se podría probar esperando un día por caso.
  // Lo que se prueba es la MÁQUINA, no el reloj.
  seg_vencer_toque: `UPDATE hpf_seguimientos
    SET proximo_at = now() - interval '1 minute', bloqueado_hasta = NULL
    WHERE session_id = $1 RETURNING session_id, proximo_at`,
  // La línea de tiempo real, comprimida: el lead escribió hace 30 h, la última ola
  // salió hace 24 h, y la evaluación vence ahora. Lo importante es que
  // `ultimo_inbound_at` quede ANTES de `evaluacion_desde_at`: eso es "estuvo callado".
  seg_vencer_eval: `UPDATE hpf_seguimientos
    SET proximo_at = NULL, ola = 3, bloqueado_hasta = NULL,
        ultimo_inbound_at   = now() - interval '30 hours',
        desde_at            = now() - interval '30 hours',
        evaluacion_desde_at = now() - interval '24 hours',
        evaluacion_at       = now() - interval '1 minute'
    WHERE session_id = $1 RETURNING session_id, evaluacion_at`,

  // Igual pero el lead SÍ escribió después de la última ola: dispara el clasificador
  // de desinterés.
  seg_vencer_eval_hablo: `UPDATE hpf_seguimientos
    SET proximo_at = NULL, ola = 3, bloqueado_hasta = NULL,
        desde_at            = now() - interval '30 hours',
        evaluacion_desde_at = now() - interval '24 hours',
        ultimo_inbound_at   = now() - interval '1 hour',
        evaluacion_at       = now() - interval '1 minute'
    WHERE session_id = $1 RETURNING session_id, ultimo_inbound_at`,
  seg_respondio: `UPDATE hpf_seguimientos
    SET proximo_at = now() - interval '1 minute', bloqueado_hasta = NULL,
        ultimo_inbound_at = now() + interval '1 minute'
    WHERE session_id = $1 RETURNING session_id, ultimo_inbound_at`,
  seg_futuro: `UPDATE hpf_seguimientos
    SET proximo_at = now() + interval '2 hours',
        bloqueado_hasta = now() - interval '1 minute'
    WHERE session_id = $1 RETURNING session_id, proximo_at`,
};

const j0 = $input.first().json || {};
const src = (j0.body && j0.body.consulta !== undefined) ? j0.body : j0;
const nombre = String(src.consulta || '');
if (!CONSULTAS[nombre]) {
  throw new Error(`W9: consulta "${nombre}" no está en la lista blanca ` +
    `(${Object.keys(CONSULTAS).join(', ')})`);
}
return [{ json: { consulta: nombre, sql: CONSULTAS[nombre],
                  param: src.param !== undefined ? String(src.param) : '%' } }];

